library(ggplot2);library(dplyr)
labels<-c(up1='PRR/TLR/NF-kB signaling',up2='Phagolysosomal/autophagy',up3='Type I IFN response',dw1='Ribosome biogenesis')
x<-read.csv('Outputs/Figure3D_HCMV_effects_complete.csv');x$host<-factor(x$host,levels=rev(names(labels)))
p<-ggplot(x,aes(Timepoint,host))+geom_point(aes(fill=beta,size=-log10(FDR_BH)),shape=21)+geom_text(aes(label=ifelse(is.na(star),'',star)),size=3)+scale_y_discrete(labels=labels)+scale_fill_gradient2(low='#8073AC',mid='#F7F7F7',high='#B35806',midpoint=0,limits=c(-.08,.08),name='HCMV effect (beta)')+scale_size_area(max_size=11,breaks=c(2,4,6),name='-log10(FDR)')+labs(x=NULL,y=NULL)+theme_bw(base_size=11)+theme(panel.grid=element_blank(),legend.box='horizontal')
ggsave('Outputs/plot_components/Figure3DE_FigureS5C_analysis_03_microbe_mod_cor_CMV.pdf',p,width=6.2,height=2.6)
y<-read.csv('Outputs/Figure3E_HCMV_effects.csv');y$host<-factor(y$host,levels=rev(names(labels)))
p<-ggplot(y,aes(beta,host))+geom_vline(xintercept=0,lty=2,color='grey60')+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',width=.12)+geom_point(size=2.5)+geom_text(aes(x=CI_high+.005,label=star),size=3)+scale_y_discrete(labels=labels)+scale_x_continuous(limits=c(-.07,.085),breaks=c(-.04,0,.04,.08))+labs(x='Adjusted beta for D1 HCMV burden',y=NULL,title='D4 module score')+theme_bw(base_size=11)+theme(panel.grid=element_blank())
ggsave('Outputs/plot_components/Figure3DE_FigureS5C_analysis_D4_module_D1_HCMV_autoregressive.pdf',p,width=5.5,height=2.6)
z<-read.csv('Outputs/FigureS5C_correlations.csv');z$host<-factor(z$host,levels=rev(names(labels)));z$microbe<-factor(z$microbe,levels=c('EBV','HCMV','TTV','Streptococcus','Staphylococcus','Prevotella','Veillonella','HPgV','Aspergillus','Mycobacterium'))
p<-ggplot(z,aes(microbe,host))+geom_point(aes(fill=rho,size=-log10(FDR_BH)),shape=21)+geom_text(aes(label=star),size=2.5)+scale_y_discrete(labels=labels)+scale_fill_gradient2(low='#E6A050',mid='#F7F7F7',high='#542788',midpoint=0,limits=c(-.3,.3),name='Spearman rho')+scale_size_area(max_size=10,breaks=c(2,4,6,8),name='-log10(FDR)')+labs(x=NULL,y=NULL)+theme_bw(base_size=10)+theme(panel.grid=element_blank(),axis.text.x=element_text(angle=45,hjust=1),legend.box='horizontal')
ggsave('Outputs/plot_components/Figure3DE_FigureS5C_analysis_03_microbe_mod_cor.pdf',p,width=8,height=3.2)
